// Checks store credentials against the real APIs before they become GitHub secrets. Reads them
// from files and environment variables, never from the command line, and never prints them.
//
//   ASC_KEY_ID=... ASC_ISSUER_ID=... ASC_KEY_PATH=AuthKey_X.p8 node check-store-access.mjs app-store <bundle id>
//   PLAY_JSON_PATH=service-account.json node check-store-access.mjs play <package name>
//
// Exit codes: 0 works, 2 the credentials work but the app is not reachable yet, 1 they do not work.
import crypto from 'node:crypto';
import fs from 'node:fs';

const b64url = (data) => Buffer.from(data).toString('base64url');

function signJwt(header, payload, key) {
  const input = `${b64url(JSON.stringify(header))}.${b64url(JSON.stringify(payload))}`;
  const signature =
    header.alg === 'ES256'
      ? crypto.sign('sha256', Buffer.from(input), { key, dsaEncoding: 'ieee-p1363' })
      : crypto.sign('sha256', Buffer.from(input), key);
  return `${input}.${b64url(signature)}`;
}

function finish(code, message) {
  console.log(`  ${code === 0 ? 'OK' : code === 2 ? 'almost' : 'FAILED'}: ${message}`);
  process.exit(code);
}

async function appStore(bundleId) {
  const { ASC_KEY_ID, ASC_ISSUER_ID, ASC_KEY_PATH } = process.env;
  let key;
  try {
    key = crypto.createPrivateKey(fs.readFileSync(ASC_KEY_PATH));
  } catch {
    finish(1, 'That .p8 file is not a readable private key.');
  }
  const now = Math.floor(Date.now() / 1000);
  const token = signJwt(
    { alg: 'ES256', kid: ASC_KEY_ID, typ: 'JWT' },
    { iss: ASC_ISSUER_ID, iat: now, exp: now + 600, aud: 'appstoreconnect-v1' },
    key,
  );
  const url = `https://api.appstoreconnect.apple.com/v1/apps?filter%5BbundleId%5D=${encodeURIComponent(bundleId)}&fields%5Bapps%5D=name,bundleId&limit=5`;
  const res = await fetch(url, { headers: { Authorization: `Bearer ${token}` } });
  if (res.status === 401) finish(1, 'App Store Connect rejected the key. Check the Key ID and the Issuer ID, and that the key was not revoked.');
  if (res.status === 403) finish(1, "The key is valid but its role can't read apps. Use a key with the App Manager (or Admin) role.");
  if (!res.ok) finish(1, `App Store Connect answered HTTP ${res.status}.`);
  const body = await res.json();
  const app = (body.data ?? []).find((a) => a.attributes?.bundleId === bundleId);
  if (!app) finish(2, `The key works, but the account has no app with bundle ID ${bundleId} yet. Create it in App Store Connect -> Apps -> + -> New App.`);
  finish(0, `App Store Connect: the key works and the app "${app.attributes.name}" exists.`);
}

async function play(packageName) {
  let sa;
  try {
    sa = JSON.parse(fs.readFileSync(process.env.PLAY_JSON_PATH, 'utf8'));
  } catch {
    finish(1, 'That file is not valid JSON.');
  }
  if (sa.type !== 'service_account' || !sa.private_key || !sa.client_email) finish(1, 'That JSON is not a Google service account key.');
  const tokenUri = sa.token_uri || 'https://oauth2.googleapis.com/token';
  const now = Math.floor(Date.now() / 1000);
  const assertion = signJwt(
    { alg: 'RS256', typ: 'JWT', kid: sa.private_key_id },
    { iss: sa.client_email, scope: 'https://www.googleapis.com/auth/androidpublisher', aud: tokenUri, iat: now, exp: now + 600 },
    crypto.createPrivateKey(sa.private_key),
  );
  const tokenRes = await fetch(tokenUri, {
    method: 'POST',
    headers: { 'content-type': 'application/x-www-form-urlencoded' },
    body: new URLSearchParams({ grant_type: 'urn:ietf:params:oauth:grant-type:jwt-bearer', assertion }),
  });
  if (!tokenRes.ok) finish(1, `Google refused the key (HTTP ${tokenRes.status}). It may have been deleted: create a new JSON key for ${sa.client_email}.`);
  const { access_token: accessToken } = await tokenRes.json();
  const auth = { Authorization: `Bearer ${accessToken}` };

  // Opening (and then deleting) an edit is the smallest call that proves release access.
  const edits = `https://androidpublisher.googleapis.com/androidpublisher/v3/applications/${encodeURIComponent(packageName)}/edits`;
  const res = await fetch(edits, { method: 'POST', headers: auth });
  if (res.ok) {
    const { id } = await res.json();
    await fetch(`${edits}/${id}`, { method: 'DELETE', headers: auth }).catch(() => {});
    finish(0, `Google Play: ${sa.client_email} can publish ${packageName}.`);
  }
  const message = (await res.json().catch(() => ({}))).error?.message ?? '';
  if (res.status === 404)
    finish(2, `The key works, but Google Play shows no app ${packageName} to it. Create the app, upload the first .aab by hand, and invite ${sa.client_email} in Play Console -> Users and permissions.`);
  if (res.status === 403)
    finish(2, `The key works, but ${sa.client_email} may not release ${packageName}: invite it in Play Console -> Users and permissions with release rights, and enable the Google Play Android Developer API in its Google Cloud project. (${message})`);
  finish(1, `Google Play answered HTTP ${res.status}. ${message}`);
}

const [kind, id] = process.argv.slice(2);
try {
  if (kind === 'app-store' && id) await appStore(id);
  else if (kind === 'play' && id) await play(id);
  else finish(1, 'Usage: check-store-access.mjs app-store <bundle id> | play <package name>');
} catch (e) {
  finish(1, `Could not reach the store (${e.message}). Check the network and try again.`);
}
